function marketCard(p){const diff=Number(p.currentValue)-Number(p.amount),pct=Number(p.amount)?100*diff/Number(p.amount):0,lang=localStorage.getItem('you-invest-language')||'en',monthsLabel=translateText(p.months+'-month portfolio',lang),riskLabel=RISK_LEVELS.find(r=>r.id===p.riskLevel)?.label||(p.riskLevel==='custom'?'Custom':'Legacy'),details=[translateText('Started',lang),new Date(Number(p.createdAt)).toLocaleDateString(getLocale()),'·',translateText(riskLabel,lang),translateText('risk',lang),'·',translateText('fixed',lang),Number(p.stopLossPct)+'%',translateText('stop',lang),...(Number(p.customFee)>0?[translateText('Fee',lang),amount(p.customFee)]:[])].join(' ');return '<button class="investment-tile" type="button" data-open-investment="'+esc(p.id)+'" aria-label="'+esc(translateText('View investment details',lang)+' · '+monthsLabel)+'"><span class="investment-tile-head"><span><b>'+esc(monthsLabel)+'</b><small>'+esc(details)+'</small></span><span class="state-badge '+(p.status==='active'?'live':p.status==='paused'?'paused':'')+'">'+esc(translateText(statusText(p.status),lang))+'</span></span><span class="investment-tile-main"><span><small>'+translateText('Reference value',lang)+'</small><strong>'+amount(p.currentValue)+'</strong></span><span class="investment-tile-change '+(diff>=0?'positive':'negative')+'">'+(diff>=0?'+':'')+pct.toFixed(2)+'%</span></span><span class="investment-tile-foot"><span>'+translateText('Principal',lang)+' <b>'+amount(p.amount)+'</b></span><span class="investment-open-label">'+translateText('Details',lang)+' <i aria-hidden="true">↗</i></span></span></button>'; }
