  const months=Number($('custom-portfolio-months').value),fee=CUSTOM_PORTFOLIO_FEES[months]||200,principal=Number($('custom-portfolio-amount').value),source=$('custom-portfolio-source').value,available=Number(state?.wallet?.[source]||0),stop=Number($('custom-portfolio-stop').value);
  const total=section.querySelectorAll('[data-custom-asset]:checked');let weightSum=0,weightsValid=total.length>0;total.forEach(check=>{const weight=Number(check.closest('.custom-asset-row').querySelector('[data-custom-weight]').value);if(!Number.isFinite(weight)||weight<=0||weight>100)weightsValid=false;weightSum+=Number.isFinite(weight)?weight:0});
