function weightedSeries(months,r){const planData=PLANS.find(p=>p.months===months);if(!planData)return[];const sets=planData.allocations.map(a=>({key:assetKeys[a.name],weight:a.weight,points:priceSeries(assetKeys[a.name],r)})).filter(x=>x.points.length>1);if(!sets.length)return[];const start=Math.max(...sets.map(x=>x.points[0].time)),end=Date.now(),out=[];for(let i=0;i<65;i++){const time=start+(end-start)*i/64;let val=0,w=0;sets.forEach(x=>{const p=x.points.reduce((b,n)=>Math.abs(n.time-time)<Math.abs(b.time-time)?n:b,x.points[0]);if(x.points[0].value>0){val+=x.weight/100*p.value/x.points[0].value;w+=x.weight/100}});if(w)out.push({time,value:100*val/w})}return out}
function renderMarketTrend(){const box=$('market-trend-indicator'),label=$('market-trend-label'),value=$('market-trend-value');if(!box||!label||!value)return;const points=weightedSeries(plan.months,'1m');if(points.length<2){box.className='market-trend neutral';label.textContent='Trend non disponibile';value.textContent='Dati di mercato insufficienti · non è una raccomandazione';return}const first=Number(points[0].value),last=Number(points[points.length-1].value),change=first?100*(last-first)/first:0,kind=change>0.5?'up':change<-.5?'down':'flat';box.className='market-trend '+kind;label.textContent=kind==='up'?'Trend recente in rialzo':kind==='down'?'Trend recente in calo':'Trend recente laterale';value.textContent=(change>0?'+':'')+change.toFixed(2)+'% · dato descrittivo, non indica il momento migliore per investire'}function market(){const list=$('asset-market-list');if(!list)return;const names=Object.keys(assetKeys);list.innerHTML=names.map(n=>{const q=getMarketQuote(n);return '<button class="asset-market-row" type="button" data-asset="'+esc(n)+'"><span class="asset-symbol">'+esc(n.slice(0,2).toUpperCase())+'</span><span class="asset-market-name"><b>'+esc(translateText(n,localStorage.getItem('you-invest-language')||'en'))+'</b><small>'+esc(translateText(q?.provider||'Quote unavailable',localStorage.getItem('you-invest-language')||'en'))+' · '+esc(q?.symbol||'')+'</small></span><span class="asset-market-price"><b>'+(q?Number(q.price).toLocaleString(getLocale(),{maximumFractionDigits:4}):'—')+'</b><small>'+esc(q?.unit||q?.currency||'')+'</small></span></button>'}).join('');list.querySelectorAll('[data-asset]').forEach(b=>b.addEventListener('click',()=>assetDialog(b.dataset.asset)));const selectors=$('plan-chart-selectors');selectors.innerHTML=rangeData.map(x=>'<button type="button" data-range="'+x[0]+'" class="chart-selector '+(x[0]===range?'active':'')+'">'+x[1]+'</button>').join('');selectors.querySelectorAll('[data-range]').forEach(b=>b.addEventListener('click',()=>{range=b.dataset.range;market()}));$('plan-history-chart').innerHTML=chart(weightedSeries(plan.months,range),translateText(plan.name,localStorage.getItem('you-invest-language')||'en'));wireChart($('plan-history-chart'));renderMarketTrend();}
function assetDialog(name){const q=getMarketQuote(name),key=assetKeys[name];$('asset-detail-title').textContent=translateText(name,localStorage.getItem('you-invest-language')||'en')+' / USD';$('asset-detail-quote').innerHTML=q?'<b>'+Number(q.price).toLocaleString(getLocale(),{maximumFractionDigits:4})+' '+esc(q.currency||'USD')+'</b><small>'+esc(q.instrument||'')+' · '+esc(q.provider||'')+' · '+(q.marketAt?new Date(q.marketAt).toLocaleString(getLocale()):'')+'</small>':'<p>Quote unavailable.</p>';const ranges=$('asset-chart-ranges');ranges.innerHTML=rangeData.map(x=>'<button type="button" data-range="'+x[0]+'" class="asset-chart-range '+(x[0]==='6m'?'active':'')+'">'+x[1]+'</button>').join('');ranges.querySelectorAll('[data-range]').forEach(b=>b.addEventListener('click',()=>{ranges.querySelectorAll('.active').forEach(x=>x.classList.remove('active'));b.classList.add('active');$('asset-detail-chart').innerHTML=chart(priceSeries(key,b.dataset.range),translateText(name,localStorage.getItem('you-invest-language')||'en'));wireChart($('asset-detail-chart'))}));$('asset-detail-chart').innerHTML=chart(priceSeries(key,'6m'),translateText(name,localStorage.getItem('you-invest-language')||'en'));wireChart($('asset-detail-chart'));open('asset-detail-dialog')}
