async function refreshNotifications(){if(!token||notificationsLoading)return;notificationsLoading=true;try{const data=await api('/api/notifications');const lang=localStorage.getItem('you-invest-language')||'en',unread=Number(data.unread)||0,badge=$('notification-count');badge.textContent=unread>99?'99+':String(unread);badge.hidden=unread===0;$('notification-dot').hidden=unread===0;$('open-notifications').setAttribute('aria-label',translateText('Notifications',lang)+(unread?' · '+unread+' '+translateText('unread',lang):''));$('mark-notifications-read').hidden=unread===0;const rows=data.notifications||[],signature=rows.map(n=>[n.id,n.title,n.message,n.created_at,n.read_at].join('|')).join('::');if(signature!==notificationSignature){const oldIds=new Set(notificationIds);const newUnread=rows.filter(n=>!n.read_at&&!oldIds.has(String(n.id)));notificationSignature=signature;notificationIds=rows.map(n=>String(n.id));$('notification-list').innerHTML=rows.map(n=>'<article class="notification-row '+(n.read_at?'':'unread')+'"><b>'+esc(translateText(n.title,lang))+'</b><small>'+new Date(Number(n.created_at)).toLocaleString(getLocale())+'</small><p>'+esc(translateText(n.message,lang))+'</p></article>').join('');if(notificationInitialized&&newUnread.length){const n=newUnread[0];notice(translateText(n.title,lang)||translateText('New notification',lang))}}notificationInitialized=true;$('notifications-empty').hidden=rows.length>0;translatePage(lang)}catch(e){console.warn('Notifications unavailable',e)}finally{notificationsLoading=false}}
