function renderAdminStatistics(data){const t=data.totals||{};const count=v=>Number(v||0).toLocaleString(getLocale());$('global-users-count').textContent=count(t.users);$('global-deposits-count').textContent=count(t.deposits_approved);$('global-deposits-total').textContent=amount(t.deposits_amount)+' · '+count(t.deposits_pending)+' pending';$('global-withdrawals-count').textContent=count(t.withdrawals_approved);$('global-withdrawals-total').textContent=amount(t.withdrawals_amount)+' · '+count(t.withdrawals_pending)+' pending';$('global-investments-count').textContent=count(t.investment_count);$('global-investments-total').textContent=amount(t.investment_amount)+' total volume';$('global-active-count').textContent=count(t.active_investments);$('global-active-total').textContent=amount(t.active_investment_amount)+' active volume';$('global-stats-breakdown').innerHTML='<div><span>All deposit requests</span><b>'+count(t.deposit_count)+'</b><small>'+amount(t.deposits_pending_amount)+' pending</small></div><div><span>All withdrawal requests</span><b>'+count(t.withdrawal_count)+'</b><small>'+amount(t.withdrawals_pending_amount)+' pending</small></div>';const rows=data.referrals||[],filter=$('admin-referral-level-filter')?.value||'all',groups=new Map();rows.forEach(r=>{if(filter!=='all'&&Number(r.level)!==Number(filter))return;if(!groups.has(r.inviter_id))groups.set(r.inviter_id,{username:r.inviter_username,rows:[]});groups.get(r.inviter_id).rows.push(r)});const markup=[...groups.values()].map(g=>{const levels=[1,2,3].filter(level=>filter==='all'||Number(filter)===level).map(level=>{const members=g.rows.filter(r=>Number(r.level)===level);if(!members.length)return '';const totals=members.reduce((a,r)=>({d:a.d+Number(r.deposit_amount||0),w:a.w+Number(r.withdrawal_amount||0),i:a.i+Number(r.investment_amount||0)}),{d:0,w:0,i:0});const items=members.map(r=>'<article class="admin-referral-user"><b>@'+esc(r.username)+'</b><small>Joined '+new Date(Number(r.created_at)).toLocaleDateString(getLocale())+'</small><span>Deposits: '+Number(r.deposits_approved||0)+' approved / '+Number(r.deposit_count||0)+' total · '+amount(r.deposit_amount)+'</span><span>Withdrawals: '+Number(r.withdrawals_approved||0)+' approved / '+Number(r.withdrawal_count||0)+' total · '+amount(r.withdrawal_amount)+'</span><span>Investments: '+Number(r.investment_count||0)+' · '+amount(r.investment_amount)+'</span></article>').join('');return '<details class="admin-referral-level"><summary><b>Level '+level+' · '+members.length+' users</b><span>Deposits '+amount(totals.d)+' · Withdrawals '+amount(totals.w)+' · Investments '+amount(totals.i)+'</span></summary><div class="admin-referral-members">'+items+'</div></details>'}).join('');return '<details class="admin-referral-inviter"><summary><b>@'+esc(g.username)+'</b><span>'+g.rows.length+' invited users</span></summary><div>'+levels+'</div></details>'}).join('');$('admin-referral-list').innerHTML=markup;$('admin-referral-empty').hidden=!!markup}
let adminStatisticsCache=null;$('invite-level-filter')?.addEventListener('change',()=>renderInvites());$('admin-referral-level-filter')?.addEventListener('change',()=>{if(adminStatisticsCache)renderAdminStatistics(adminStatisticsCache)});
function renderAdmin(){document.querySelectorAll('.view').forEach(v=>v.classList.toggle('active',v.id==='view-admin'));loadAdminDepositAddresses();api('/api/admin/statistics').then(data=>{adminStatisticsCache=data;renderAdminStatistics(data)}).catch(e=>console.warn('Admin statistics unavailable',e));api('/api/admin/transactions').then(async data=>{[['deposit',data.deposits||[],'pending-deposits','pending-deposit-count'],['withdrawal',data.withdrawals||[],'pending-withdrawals','pending-withdrawal-count'],['wallet_change',data.walletChanges||[],'pending-wallet-changes','pending-wallet-count']].forEach(([kind,rows,target,count])=>{if($(count))$(count).textContent=String(rows.length);if($(target))$(target).innerHTML=rows.map(r=>'<article class="admin-request"><b>@'+esc(r.username||'user')+' · '+esc(r.net||'')+'</b><span>'+esc(r.tx_reference||r.wallet_address||'')+' '+(r.amount?amount(r.amount):'')+'</span><small>'+new Date(r.date||r.created_at).toLocaleString(getLocale())+'</small>'+(kind==='withdrawal'?'<label class="admin-tx-field">'+translateText('Verified on-chain transaction hash',localStorage.getItem('you-invest-language')||'en')+'<input class="withdrawal-tx-input" type="text" maxlength=66 placeholder="0x… or 64-character hash" value="'+esc(r.tx_reference||'')+'" autocomplete="off" required></label><small class="admin-tx-hint">'+translateText('Confirm this hash on the correct explorer before approving.',localStorage.getItem('you-invest-language')||'en')+'</small>':'')+'<div><button data-review="approve" data-kind="'+kind+'" data-id="'+r.id+'">Approve</button><button data-review="reject" data-kind="'+kind+'" data-id="'+r.id+'">Reject</button></div></article>').join('')||'<p class="queue-empty">No pending requests.</p>'});const ver=data.emailVerifications||[],resets=data.passwordResets||[];$('pending-email-verifications').innerHTML=ver.map(r=>'<article class="admin-request"><b>@'+esc(r.username)+' · '+esc(r.identifier)+'</b><small>Requested '+new Date(r.requested_at).toLocaleString(getLocale())+(r.otp_expires_at&&Number(r.otp_expires_at)>Date.now()?' · Code issued, valid for a limited time':'')+'</small><button data-issue-otp="verify" data-user="'+encodeURIComponent(r.user_id)+'">Issue OTP · 15 min</button></article>').join('')||'';$('email-verification-queue-empty').hidden=ver.length>0;$('pending-password-resets').innerHTML=resets.map(r=>'<article class="admin-request"><b>@'+esc(r.username)+' · '+esc(r.identifier)+'</b><small>Requested '+new Date(r.requested_at).toLocaleString(getLocale())+(r.issued_at?' · Code issued; request remains open until completion':'')+'</small><button data-issue-otp="reset" data-user="'+encodeURIComponent(r.user_id)+'">Issue OTP · 15 min</button></article>').join('')||'';$('password-reset-queue-empty').hidden=resets.length>0;try{const users=await api('/api/admin/users');renderAdminUsers(users.users||[])}catch{}}).catch(e=>notice(e.message,true))}
$('open-admin').addEventListener('click',renderAdmin);
$('view-admin').addEventListener('click',async e=>{const otp=e.target.closest('[data-issue-otp]');if(otp){const bytes=new Uint32Array(1);crypto.getRandomValues(bytes);const code=String(bytes[0]%1000000).padStart(6,'0');const isVerify=otp.dataset.issueOtp==='verify',route=isVerify?'verification-otp':'password-reset-otp';try{await post('/api/admin/users/'+decodeURIComponent(otp.dataset.user)+'/'+route,{otp:code});adminOtpActiveUntil=Date.now()+120000;const row=otp.closest('.admin-request');let result=row.querySelector('.otp-issued');if(!result){result=document.createElement('div');result.className='otp-issued';row.append(result)}const codeEl=document.createElement('code');codeEl.textContent=code;const copy=document.createElement('button');copy.type='button';copy.textContent='Copy code';copy.addEventListener('click',async()=>{try{await navigator.clipboard.writeText(code);notice('OTP copied. Share it only via the verified contact channel.')}catch{notice('Copy unavailable. Select the displayed code.',true)}});result.replaceChildren(document.createTextNode(isVerify?'Issued · valid for 15 minutes · email manually. ':'Issued · valid for 15 minutes. Share through a verified contact channel: '),codeEl,copy);notice(isVerify?'Verification code ready to email.':'Recovery code issued. Share it through a verified contact channel.')}catch(x){notice(x.message,true)}return}const b=e.target.closest('[data-review]');if(!b)return;try{const payload={kind:b.dataset.kind,id:Number(b.dataset.id),action:b.dataset.review};if(payload.kind==='withdrawal'&&payload.action==='approve'){payload.txReference=(b.closest('.admin-request')?.querySelector('.withdrawal-tx-input')?.value||'').trim();if(!payload.txReference){notice('Enter the verified on-chain transaction hash before approving.',true);return}}await post('/api/admin/review',payload);renderAdmin()}catch(x){notice(x.message,true)}});
try{const pref=JSON.parse(localStorage.getItem('you-invest-preferences')||'{}');if(pref.theme)$('theme-select').value=pref.theme;document.documentElement.dataset.theme=pref.theme||'dark';$('theme-select').addEventListener('change',e=>{document.documentElement.dataset.theme=e.target.value;localStorage.setItem('you-invest-preferences',JSON.stringify({...pref,theme:e.target.value}))})}catch{}
function applyLanguage(){let lang='en';try{lang=localStorage.getItem('you-invest-language')||'en'}catch{}const a=$('language-select'),b=$('landing-language-select');if(a)a.value=lang;if(b)b.value=lang;translatePage(lang)}['language-select','landing-language-select'].forEach(id=>{const el=$(id);if(el)el.addEventListener('change',()=>{localStorage.setItem('you-invest-language',el.value);if(state)render();else applyLanguage();if(selectedInvestmentId&&$('investment-detail-dialog').open)renderInvestmentDetail(selectedInvestmentId);if(token)refreshNotifications()})});
(async()=>{if(adminToken){try{await api('/api/admin/transactions');state={};app();startPolling();return}catch{adminToken='';localStorage.removeItem(ADMIN)}}if(token){try{state=await api('/api/me');app();startPolling();return}catch{token='';localStorage.removeItem(TOKEN)}}landing()})();

